declare
  n_id					Number;
  v_cuti				Varchar2(10);
  v_old_cb				Varchar2(20);
BEGIN
  v_cuti := '.';
  If inserting Then
	 v_old_cb	 := '-';
  Else
	 v_old_cb	 := :old.codbarre;
  End if;


  If v_old_cb != :new.codbarre Then
	 Select seq_pfi_queue_id.nextval Into n_id From Dual;

	 Insert into Gc_pfi_queue (id, codart, tarif, datcre, cuti) values (n_id, :new.codart, null, sysdate, Nvl(v_cuti,'.'));
  End if;
END;

declare
  n_id					Number;
  v_cuti				Varchar2(10);
  v_old_lib				Varchar2(100);
  v_old_cb				Varchar2(30);
  n_old_tarif			Number;
  n_new_tarif			Number;
BEGIN
  If inserting Then
     v_cuti := :new.cuti;
	 n_old_tarif := 0;
	 v_old_lib	 := '-';
  Elsif updating Then
     v_cuti := Nvl(:new.muti,:new.cuti);
	 n_old_tarif := :old.tarifstd;
	 v_old_lib	 := :old.libart||:old.libart2;
	 v_old_cb	 := :old.codbarre;
  Elsif deleting Then
	 Select seq_pfi_queue_id.nextval Into n_id From Dual;

	 Insert into Gc_pfi_queue (id, codart, tarif, datcre, cuti) values (n_id, :old.codart, null, sysdate, Nvl(v_cuti,'.'));

	 Return;
  End if;


  If :new.promo='O' and :new.pro_ddeb is not null and :new.pro_dfin is not null and nvl(:new.tarifpro,0) != 0
     and trunc(sysdate,'dd') between :new.pro_ddeb and :new.pro_dfin Then
	 n_new_tarif := :new.tarifpro;
  Else
	 n_old_tarif := :new.tarifpro;
	 n_new_tarif := :new.tarifstd;
  End if;

  If Nvl(n_old_tarif,0) != Nvl(n_new_tarif,0) or substr(v_old_lib,1,25) != substr(:new.libart||:new.libart2,1,25) or v_old_cb != :new.codbarre Then
	 Select seq_pfi_queue_id.nextval Into n_id From Dual;

	 Insert into Gc_pfi_queue (id, codart, tarif, datcre, cuti) values (n_id, :new.codart, n_new_tarif, sysdate, Nvl(v_cuti,'.'));
  End if;
END;

declare

  v_exonere		Varchar2(1);
  n_ttaxe		GCPTARIF.ttaxe_tarif%TYPE;
BEGIN
	If :new.codrtax is not null Then
		 Select max(exonere) Into v_exonere From KERNEL.Utprtax
		  Where codrtax = :new.codrtax;
	End if;

	If v_exonere = 'O' Then
		 n_ttaxe := 0;
	Else		
	   SELECT max(ttaxe_tarif) INTO n_ttaxe FROM GCPTARIF
	    WHERE codtarif = '0';
	End if;    

  IF NVL(n_ttaxe,0) = 0 THEN
  	 :new.tarifstd_ht := :new.tarifstd;  	 
  ELSE
  	 :new.tarifstd_ht := :new.tarifstd / (1+(n_ttaxe/100));
  END IF;
end;

