declare

  v_exonere		Varchar2(1);
  n_ttaxe		GCPTARIF.ttaxe_tarif%TYPE;
  v_codrtax		GCPART.codrtax%TYPE;
BEGIN
  Select codrtax Into v_codrtax From Gcpart
   Where codart = :new.codart;  
	If v_codrtax is not null Then
		 Select max(exonere) Into v_exonere From KERNEL.Utprtax
		  Where codrtax = v_codrtax;
	Else
		 v_exonere := 'N'; 
	End if;

	If v_exonere = 'O' Then
		 n_ttaxe := 0;
	Else		
	   SELECT max(ttaxe_tarif) INTO n_ttaxe FROM GCPTARIF
	    WHERE codtarif = :new.codtarif;
	End if;    

  IF NVL(n_ttaxe,0) = 0 THEN
  	 :new.tarif_ht := :new.tarif;  	 
  ELSE
  	 :new.tarif_ht := :new.tarif / (1+(n_ttaxe/100));
  END IF;
end;

declare
  v_sens 	gcptrgl.sens%type;
  v_codtrgl	gcrgle.codtrgl%type;

  n_der_idbrd	gcrgld.idbrd%type;
  n_mtvent	gcrgld.mtrgl%type;
  n_mtrgl	gcrgld.mtrgl%type;
  n_mttc	gcbrde.mttc%type;
begin
  if (deleting or updating) then
    begin
      select codtrgl into v_codtrgl from gcrgle
       where idrgl = :old.idrgl;
    end;

    begin
      select sens into v_sens
        from gcptrgl
       where codtrgl = v_codtrgl;
    exception
      when no_data_found then
        raise_application_error (-20501,'Type de règlement inconnu');
    end;


    select sum(mttc) INTO n_mttc from gcbrde
     where (  (:old.idbrd is not null and idbrd=:old.idbrd)
	    or(:old.idbrd is null and codtbrd=:old.codtbrd and numfac=:old.numfac)
	   );

    n_mtvent := 0;
    for c1_row IN (select idbrd, mttc from gcbrde
		    where (  (:old.idbrd is not null and idbrd=:old.idbrd)
			   or(:old.idbrd is null and codtbrd=:old.codtbrd and numfac=:old.numfac)
			  ))
    loop
       n_mtrgl := ROUND( (c1_row.mttc/n_mttc)*:old.mtrgl ,0);
       n_mtvent :=  n_mtvent + n_mtrgl;

       update gcbrde set mtrgl = nvl(mtrgl,0) + n_mtrgl*DECODE(v_sens,'D',-1,1)
	where idbrd = c1_row.idbrd;
       n_der_idbrd := c1_row.idbrd;
    end loop;

    if n_mtvent != n_mttc then
       update gcbrde set mtrgl = nvl(mtrgl,0) + (:old.mtrgl - n_mtvent)*DECODE(v_sens,'D',-1,1)
	where idbrd = n_der_idbrd;
    end if;

  end if;

  if (inserting or updating) then
    begin
      select codtrgl into v_codtrgl from gcrgle
       where idrgl = :new.idrgl;
    end;

    begin
      select sens into v_sens
        from gcptrgl
       where codtrgl = v_codtrgl;
    exception
      when no_data_found then
        raise_application_error (-20501,'Type de règlement inconnu');
    end;


    select sum(mttc) INTO n_mttc from gcbrde
     where (  (:new.idbrd is not null and idbrd=:new.idbrd)
	    or(:new.idbrd is null and codtbrd=:new.codtbrd and numfac=:new.numfac)
	   );

    n_mtvent := 0;
    for c1_row IN (select idbrd, mttc from gcbrde
		    where (  (:new.idbrd is not null and idbrd=:new.idbrd)
			   or(:new.idbrd is null and codtbrd=:new.codtbrd and numfac=:new.numfac)
			  ))
    loop
       n_mtrgl := ROUND( (c1_row.mttc/n_mttc)*:new.mtrgl ,0);
       n_mtvent :=  n_mtvent + n_mtrgl;

       update gcbrde set mtrgl = nvl(mtrgl,0) + n_mtrgl*DECODE(v_sens,'D',1,-1)
	where idbrd = c1_row.idbrd;
       n_der_idbrd := c1_row.idbrd;
    end loop;

    if n_mtvent != n_mttc then
       update gcbrde set mtrgl = nvl(mtrgl,0) + (:new.mtrgl - n_mtvent)*DECODE(v_sens,'D',1,-1)
	where idbrd = n_der_idbrd;
    end if;
  end if;
end;

declare
  n_count		 Number;
  b_notconcern	 Boolean;
  v_valc		 Gcppar.valc%Type;
BEGIN
  -- PARGEN / SWF : STOCK WARM FOURN A EXCLURE
  Select max(valc) Into v_valc From Gcppar
   Where codpar='PARGEN' and cle='SWF';

  If v_valc is null Then
     b_notconcern := False;
  Else
	 Select count(*) Into n_count From Gcpart Where codart=:new.codart and v_valc like '%'||codfrnprinc||';%';
	 b_notconcern := (n_count > 0);
  End if;

  If b_notconcern Then
	 Delete gcstock_warm where codart=:new.codart and coddep=:new.coddep;
  ElsIf :new.qtestock < 0 Then
	 Select count(*) Into n_count From gcstock_warm where codart=:new.codart and coddep=:new.coddep;
	 If n_count = 0 Then
		Insert into gcstock_warm (codart, coddep, quantite, datdep) values (:new.codart, :new.coddep, :new.qtestock, Trunc(sysdate,'dd'));
	 Else
		Update gcstock_warm set quantite=:new.qtestock where codart=:new.codart and coddep=:new.coddep;
	 End if;
  Elsif :new.qtestock >= 0 Then
	 Delete gcstock_warm where codart=:new.codart and coddep=:new.coddep;
  End if;
end;

