declare
  v_sens 	    caicodmvt.sens%type;
  n_solde 	caicaisse.solde_caisse%type ;
begin
  if (deleting or updating) and :old.etat != 'A' then
    begin
      select sens into v_sens
        from caicodmvt
       where codmvt = :old.codmvt;
    exception
      when no_data_found then
        raise_application_error (-20501,'Code mouvement inconnu');
    end;
    begin
      select solde_caisse into n_solde
        from caicaisse
       where codcai=:old.codcai;
    exception
      when no_data_found then
        raise_application_error (-20502,'Fiche stock introuvable');
    end;

    -- Mise à jour du chanp SOLDE_CAISSE
    if v_sens = 'R' then
       update caicaisse
          set solde_caisse = nvl(solde_caisse,0) - :old.montant
        where codcai=:old.codcai;
    else
          update caicaisse
             set solde_caisse = nvl(solde_caisse,0) + :old.montant
        where codcai=:old.codcai;
    end if;

  end if;

  if (inserting or updating) and :new.etat != 'A' then
    begin
      select sens into v_sens
        from caicodmvt
       where codmvt = :new.codmvt;
    exception
      when no_data_found then
        raise_application_error (-20501,'Code mouvement inconnu');
    end;
    begin
      select solde_caisse into n_solde
        from caicaisse
       where codcai=:new.codcai;
    exception
      when no_data_found then
        raise_application_error (-20502,'Code caisse introuvable');
    end;

    -- Mise à jour du chanp SOLDE_CAISSE
    if v_sens = 'R' then
       update caicaisse
          set solde_caisse = nvl(solde_caisse,0) + :new.montant
        where codcai=:new.codcai;
    else
          update caicaisse
             set solde_caisse = nvl(solde_caisse,0) - :new.montant
        where codcai=:new.codcai;
    end if;
  end if;
end;

